// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint64 blk) public {
        vm.assume(caller != address(0));

        vm.deal(caller, 20 ether);
        vm.deal(address(c), 10 ether);

        uint64 targetBlock = blk;
        if (targetBlock % 15 == 0) { targetBlock += 1; }

        vm.warp(block.timestamp + 1);
        vm.roll(uint256(targetBlock));

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        assertTrue(address(c).balance > 0);
    }
}
